syntax:
void copy_assign(Object *dest, const Object *src); // Performs deep copy of src into dest
void destructor(Object *obj); // Cleans up resources held by obj

// Usage pattern:
Object obj1, obj2;
initialize(&obj1);
initialize(&obj2);
copy_assign(&obj2, &obj1); // Deep copy
// ... use objects ...
destructor(&obj1);
destructor(&obj2);
